begin;
insert into public.ce_course3_resources(id,data) values
('course3_module9_pdf','{"base64": "", "sha256": "6c6f02fc331cc26c473332c000030baee429ca6b930681c32746bf13832f1fb4", "filename": "CE_HALO_Course3_Module09_HIPAA_Privacy_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course3_module9_questions','[{"module_id": "course_3_module_9", "question_id": "course_3_module_9_q01", "question_number": 1, "stem": "Which of the following most accurately describes the three core HIPAA rules that apply to CRNA practice?", "choice_a": "Privacy Rule (uses and disclosures of PHI), Security Rule (safeguards for ePHI), and Breach Notification Rule (response to impermissible use or disclosure of unsecured PHI)", "choice_b": "Federal Rule, State Rule, and Facility Rule", "choice_c": "Meaningful Use Rule, MACRA Rule, and Interoperability Rule", "choice_d": "Consent Rule, Encryption Rule, and Litigation Rule", "correct_choice": "a", "rationale": "HIPAA''s three core rules relevant to CRNAs are the Privacy Rule (45 CFR §§164.500–164.534), the Security Rule (§§164.302–164.318), and the Breach Notification Rule (§§164.400–164.414).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q02", "question_number": 2, "stem": "Under the HIPAA Privacy Rule, disclosure of PHI for treatment, payment, and health-care operations (TPO):", "choice_a": "Is only permitted for treatment, never for payment or operations", "choice_b": "Is generally permitted without separate written authorization when the disclosure supports patient care and complies with organizational safeguards (45 CFR §164.506)", "choice_c": "Requires a signed HIPAA authorization every time", "choice_d": "Is prohibited without a court order", "correct_choice": "b", "rationale": "45 CFR §164.506 permits use and disclosure of PHI for TPO without separate written authorization when the disclosure supports patient care and complies with safeguards.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q03", "question_number": 3, "stem": "The minimum necessary standard (45 CFR §164.502(b)) generally does NOT apply to which of the following disclosures?", "choice_a": "A disclosure to a business associate for billing", "choice_b": "A disclosure for a quality improvement project", "choice_c": "A disclosure by one health-care provider to another for treatment", "choice_d": "A disclosure for peer review", "correct_choice": "c", "rationale": "The minimum necessary standard does not restrict disclosures to or requests by a health-care provider for treatment (nor disclosures to the patient, under valid authorization, to HHS, required by law, or required for compliance).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q04", "question_number": 4, "stem": "A CRNA opens the chart of a coworker who was admitted overnight for a minor surgery, out of concern, and does not share the information. Which statement is most accurate?", "choice_a": "This is acceptable because no information was shared", "choice_b": "This is acceptable if the coworker is a friend", "choice_c": "This is only a violation if the coworker complains", "choice_d": "This may still constitute a HIPAA violation — technical ability to access a chart does not equal authorization, and audit controls will detect the access", "correct_choice": "d", "rationale": "Under 45 CFR §164.312(b), audit controls track access. Opening a chart without a care-related or approved purpose is unauthorized access even if no information is shared — a \"no harm intended\" defense is not valid.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q05", "question_number": 5, "stem": "Which of the following are required elements of a Business Associate Agreement (BAA) under 45 CFR §164.504(e)?", "choice_a": "Permitted uses of PHI, safeguards, breach and security-incident reporting, subcontractor flow-down, patient-rights support, HHS access, return/destruction of PHI at termination, and termination authority for material breach", "choice_b": "Only fee-schedule and payment terms", "choice_c": "Only encryption requirements", "choice_d": "Only insurance coverage and indemnification", "correct_choice": "a", "rationale": "45 CFR §164.504(e) enumerates the required elements: permitted/required uses, safeguards, breach/incident reporting, subcontractor flow-down, patient-rights support, HHS access, return/destruction at termination, and termination authority for material breach.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q06", "question_number": 6, "stem": "The 2024 Change Healthcare cyberattack is significant to CRNA practice primarily because:", "choice_a": "It was limited to dental practices", "choice_b": "It was a business-associate compromise that ultimately affected approximately 190 million individuals — the largest health-care data breach in U.S. history — and disrupted anesthesia group billing, prior authorization, and claims for months", "choice_c": "It has no relevance to HIPAA", "choice_d": "It only affected physician offices, not CRNAs", "correct_choice": "b", "rationale": "The February 2024 Change Healthcare ransomware event affected ~190 million individuals via a business associate and disrupted health-care operations nationwide, illustrating business-associate risk and reinforcing the need for BAAs and cybersecurity controls.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q07", "question_number": 7, "stem": "Which of the following was proposed in the December 2024 HIPAA Security Rule Notice of Proposed Rulemaking (NPRM)?", "choice_a": "Repeal of the Breach Notification Rule", "choice_b": "Elimination of the Privacy Rule", "choice_c": "Elimination of the addressable/required distinction; mandatory encryption of ePHI; multi-factor authentication; written risk analyses and asset inventories; incident-response timelines; and annual business-associate written verification", "choice_d": "Removal of patient right-of-access requirements", "correct_choice": "c", "rationale": "The 2024 NPRM (89 Fed. Reg. 101340) proposes to eliminate addressable specifications, mandate encryption and MFA, require written risk analyses and asset inventories, impose contingency/incident timelines, and require annual written business-associate assurances.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q08", "question_number": 8, "stem": "Per the HIPAA Breach Notification Rule, a covered entity must notify affected individuals of a breach of unsecured PHI:", "choice_a": "Within 30 days of the impermissible use or disclosure", "choice_b": "Only at annual reporting", "choice_c": "Only if more than 1,000 individuals are affected", "choice_d": "Without unreasonable delay and no later than 60 calendar days after discovery of the breach", "correct_choice": "d", "rationale": "45 CFR §164.404 requires individual notification without unreasonable delay and in no case later than 60 calendar days after discovery of the breach.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q09", "question_number": 9, "stem": "For breaches affecting 500 or more individuals in a state or jurisdiction, the covered entity must:", "choice_a": "Notify affected individuals, notify HHS contemporaneously (and in no case later than 60 calendar days after discovery), and notify prominent media outlets serving the state or jurisdiction", "choice_b": "Notify only the HHS Secretary annually", "choice_c": "Notify only the affected individuals", "choice_d": "Notify only the state attorney general", "correct_choice": "a", "rationale": "For breaches ≥500 individuals in a state or jurisdiction, 45 CFR §164.406–164.408 require individual notice, contemporaneous HHS notice (no later than 60 days), and media notice in that state or jurisdiction.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q10", "question_number": 10, "stem": "A business associate that discovers a breach of unsecured PHI must notify the covered entity:", "choice_a": "Only at contract renewal", "choice_b": "Without unreasonable delay and no later than 60 calendar days after discovery of the breach at the business associate", "choice_c": "Within 30 calendar days", "choice_d": "Within 7 calendar days", "correct_choice": "b", "rationale": "45 CFR §164.410 requires business associates to notify the covered entity without unreasonable delay and no later than 60 calendar days after discovery of the breach.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q11", "question_number": 11, "stem": "A CRNA needs to text an on-call anesthesiologist about an add-on case with the patient''s medical record number and airway concern. Which channel is HIPAA-compliant?", "choice_a": "Standard SMS from a personal iPhone", "choice_b": "WhatsApp", "choice_c": "A facility-approved secure clinical messaging platform (e.g., TigerConnect, Halo Health, Epic Secure Chat, Vocera) that provides encryption, audit logging, unique authentication, and operates under a BAA", "choice_d": "iMessage between personal phones", "correct_choice": "c", "rationale": "Consumer SMS/iMessage/WhatsApp typically lack HIPAA safeguards and lack a BAA. Only facility-approved secure clinical messaging platforms meet Security Rule transmission-security and audit requirements.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q12", "question_number": 12, "stem": "A CRNA takes a photo of an interesting airway with a personal phone during a case, intending to use it later for teaching. Which of the following is the most correct action?", "choice_a": "The photo can be posted to a private social-media group", "choice_b": "The photo is fine because HIPAA does not cover images", "choice_c": "The photo is fine if the patient''s face is not visible", "choice_d": "The photo should have been taken with an approved facility image-capture system with any required consent; taking or storing identifiable images on a personal device is not compliant with the Security Rule and organizational policy, even if the face is obscured", "correct_choice": "d", "rationale": "Clinical photography must occur via approved equipment and storage. Wristbands, MRN visibility, monitor detail, or surrounding context can still make an image identifiable. Personal-device storage of identifiable images generally violates policy and HIPAA.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q13", "question_number": 13, "stem": "A CRNA posts a de-identified anesthesia \"war story\" on social media describing an unusual airway complication during a high-profile trauma at their hospital. Which statement is most accurate?", "choice_a": "This may still be a HIPAA violation because timing, location, diagnosis, procedure, image details, or community context can make the patient identifiable — nurse-related discipline for such posts is well-documented", "choice_b": "It''s acceptable as long as friends only see the post", "choice_c": "This is fine because no name was used", "choice_d": "Social media is not covered by HIPAA", "correct_choice": "a", "rationale": "OCR and boards of nursing have consistently found that \"de-identified\" case posts can still identify a patient through community context. Do not post clinical detail without organizational authorization and any required patient authorization.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q14", "question_number": 14, "stem": "Under the 2024 inflation-adjusted HITECH civil monetary penalty tiers, which tier applies to violations attributable to willful neglect that are NOT corrected within 30 days?", "choice_a": "Tier 2 (reasonable cause, not willful neglect)", "choice_b": "Tier 4 (willful neglect, not corrected within 30 days) — with the highest per-violation minimums and maximums, up to the annual cap", "choice_c": "Tier 1 (no knowledge)", "choice_d": "Tier 3 (willful neglect, corrected within 30 days)", "correct_choice": "b", "rationale": "42 USC §1320d-5 and 45 CFR §160.404 establish four tiers. Tier 4 (willful neglect, not corrected within 30 days) carries the highest minimum (~$68,928) and maximum per violation, subject to the annual cap.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q15", "question_number": 15, "stem": "A patient requests a copy of their anesthesia record. What is the CRNA''s most correct action under the Right of Access Rule (45 CFR §164.524)?", "choice_a": "Print the record and hand it to the patient at bedside", "choice_b": "Refuse because CRNAs cannot release records", "choice_c": "Route the request through the organization''s release-of-information process so identity verification, timeline (generally 30 days), format, cost-based fee, and any denial-review procedure are handled correctly", "choice_d": "Email the record from a personal account", "correct_choice": "c", "rationale": "Patients have a right of access, but release requires identity verification, form/format handling, and reasonable fee calculation. Route through release-of-information; informal release bypasses controls and audit trail.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q16", "question_number": 16, "stem": "Under 45 CFR §164.524, generally within how many calendar days must a covered entity provide a patient with requested access to their PHI (with a one-time extension of up to 30 additional days permitted)?", "choice_a": "180 calendar days", "choice_b": "10 calendar days", "choice_c": "60 calendar days", "choice_d": "30 calendar days", "correct_choice": "d", "rationale": "45 CFR §164.524 requires access to be provided generally within 30 calendar days, with a one-time 30-day extension permitted if the patient is notified in writing with the reason.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q17", "question_number": 17, "stem": "Which of the following best describes OCR''s Right of Access Initiative as reflected in 2024–2025 enforcement?", "choice_a": "OCR has announced 50+ Right of Access settlements against covered entities that failed to provide timely, reasonably-priced patient access — including 2024–2025 settlements ranging from $15,000 to over $200,000", "choice_b": "OCR settlements have all been over $10 million", "choice_c": "OCR only enforces breach notification, not access rights", "choice_d": "OCR has abandoned right-of-access enforcement", "correct_choice": "a", "rationale": "OCR has publicly announced 50+ Right of Access settlements, including 2024–2025 settlements from $15,000 to over $240,000 for failure to provide timely, reasonable-fee patient access.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q18", "question_number": 18, "stem": "Under HIPAA, a successful ransomware attack that encrypts electronic PHI is:", "choice_a": "Only reportable if the ransom is paid", "choice_b": "Presumed to be a reportable breach unless the covered entity demonstrates a low probability that PHI was compromised under the four-factor risk assessment (45 CFR §164.402)", "choice_c": "Only a breach if patients complain", "choice_d": "Never a breach because the attacker did not view the data", "correct_choice": "b", "rationale": "OCR guidance treats ransomware infection of ePHI as a presumed breach because attacker encryption is an impermissible acquisition; the covered entity must demonstrate low probability of compromise via the four-factor assessment.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q19", "question_number": 19, "stem": "Which of the following is a Security Rule technical safeguard under 45 CFR §164.312?", "choice_a": "Facility access control (badge access)", "choice_b": "Sanction policies", "choice_c": "Unique user identification, automatic logoff, encryption, audit controls, and transmission security", "choice_d": "Workforce training", "correct_choice": "c", "rationale": "45 CFR §164.312 covers technical safeguards — unique user identification, automatic logoff, encryption/decryption, audit controls, integrity, authentication, and transmission security. Training and sanctions are administrative; badge access is physical.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q20", "question_number": 20, "stem": "A CRNA discovers that an unencrypted personal laptop containing a spreadsheet of preop patient identifiers has been stolen from her car. What is the most appropriate initial action?", "choice_a": "Say nothing and try to buy a replacement laptop", "choice_b": "Wait to see if the laptop is returned before reporting anything", "choice_c": "Post about the theft on social media to see if anyone has seen it", "choice_d": "Report immediately through the organization''s incident/privacy channel so risk assessment, containment, breach evaluation, and any required notification timeline can begin — and cooperate with the investigation", "correct_choice": "d", "rationale": "Prompt internal reporting is essential; delays interfere with containment, four-factor breach analysis, notification timelines (60-day maximum), and mitigation. The unencrypted device also creates a Security Rule concern.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q21", "question_number": 21, "stem": "Under 45 CFR §164.522(a)(1)(vi), a covered entity is REQUIRED to agree to a patient''s requested restriction on disclosure of PHI to a health plan when:", "choice_a": "The patient has paid in full out of pocket for the relevant service and the disclosure is for payment or health-care operations and is not otherwise required by law", "choice_b": "The health plan waives the requirement", "choice_c": "The service was elective", "choice_d": "The patient asks in writing regardless of payment status", "correct_choice": "a", "rationale": "45 CFR §164.522(a)(1)(vi) requires the covered entity to honor the restriction when the patient has paid in full out of pocket and the disclosure to a health plan is for payment or operations and is not otherwise required by law.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q22", "question_number": 22, "stem": "A CRNA is asked by a vendor demonstrating a new anesthesia device to email de-identified case examples to the vendor''s training team. Which of the following is most correct?", "choice_a": "Send from a personal email account for convenience", "choice_b": "Confirm the vendor is on the approved list with a signed BAA if PHI is involved, ensure any de-identification meets HIPAA Safe-Harbor or Expert-Determination standards (45 CFR §164.514), and use organization-approved communication channels", "choice_c": "Upload to the vendor''s public cloud folder", "choice_d": "Send freely — de-identification removes HIPAA obligations", "correct_choice": "b", "rationale": "If PHI is involved, a BAA is required. If truly de-identified per §164.514 Safe-Harbor (removal of 18 identifiers) or Expert Determination, HIPAA no longer applies — but the CRNA must ensure the standard is met and use approved channels.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q23", "question_number": 23, "stem": "A patient in the PACU objects to disclosure of any of her clinical information to her adult son who has been in the waiting room. What is the CRNA''s appropriate response?", "choice_a": "Ignore the patient''s objection because HIPAA requires family notification", "choice_b": "Provide the son with a full clinical update because he is family", "choice_c": "Respect the patient''s objection; when the patient is present and has decision-making capacity, HIPAA (45 CFR §164.510(b)) generally permits the patient to agree, object, or restrict disclosure to family or friends", "choice_d": "Ask the son for his authorization", "correct_choice": "c", "rationale": "45 CFR §164.510(b) allows the patient with capacity, when present, to agree or object to disclosure to family or friends. The CRNA must respect the objection.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q24", "question_number": 24, "stem": "Which of the following is a HIPAA-compliant use of an anesthesia record for education?", "choice_a": "Posting the record on a personal blog with the patient''s name removed", "choice_b": "Sharing the record on a public online forum", "choice_c": "Emailing the record to friends outside the organization", "choice_d": "Presenting the case at a facility-sponsored M&M; or educational conference using de-identified information, or using identifiable information only when consistent with organizational policy and any required authorization", "correct_choice": "d", "rationale": "Approved educational use — with de-identification when possible, or identifiable information only when policy and any required authorization support it — is permissible. Personal blogs, public forums, and outside emails are not.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_9", "question_id": "course_3_module_9_q25", "question_number": 25, "stem": "Criminal penalties under 42 U.S.C. §1320d-6 for a person who obtains individually identifiable health information under false pretenses can include:", "choice_a": "Up to $100,000 and 5 years imprisonment", "choice_b": "Up to $50,000 and 1 year imprisonment", "choice_c": "Up to $250,000 and 10 years imprisonment", "choice_d": "A written warning only", "correct_choice": "a", "rationale": "42 USC §1320d-6 imposes up to $50,000/1 year for a knowing violation, up to $100,000/5 years when committed under false pretenses, and up to $250,000/10 years when committed with intent to sell, transfer, or use PHI for personal gain, commercial advantage, or malicious harm.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
on conflict(id) do update set data=excluded.data;
do $$ begin
assert (select encode(sha256(decode(data->>'base64','base64')),'hex')=data->>'sha256' from public.ce_course3_resources where id='course3_module9_pdf'),'PDF hash mismatch';
assert (select released=false from public.ce_course3_catalog where id='1047243'),'Course must remain staged';
end $$;
commit;